\u043d\\u0430 non-causal Hyena \\u043f\\u043e \\u043e\\u0441\\u0438 \\u0442\\u0440\\u0430\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\\u0438 (\\u043f\\u0440\\u0438 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0438\\u0440\\u0443\\u0435\\u043c\\u043e\\u0439 \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0451\\u043c\\u043a\\u043e\\u0441\\u0442\\u0438) \\u043d\\u0435 \\u0443\\u043b\\u0443\\u0447\\u0448\\u0430\\u0435\\u0442 \\u043d\\u0438 \\u043e\\u0434\\u043d\\u0443 \\u0438\\u0437 M1, M2, M3, M4 \\u043e\\u0442\\u043d\\u043e\\u0441\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u0430 (a) \\u0432 pre-registered \\u0434\\u0438\\u0430\\u043f\\u0430\\u0437\\u043e\\u043d\\u0435.\\n- **H1** \\u2014 \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442 (d) non-causal Hyena \\u043f\\u0440\\u0435\\u0432\\u043e\\u0441\\u0445\\u043e\\u0434\\u0438\\u0442 (a) \\u043f\\u043e (M1 mid/high \\u043f\\u0440\\u0438 T\\u22651024) \\u2227 (M3 H=256) \\u2227 \\u043d\\u0435 \\u0443\\u0441\\u0442\\u0443\\u043f\\u0430\\u0435\\u0442 \\u043f\\u043e M4 \\u2014 \\u043e\\u0434\\u043d\\u043e\\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u043e.\\n\\n\\u041b\\u043e\\u0433\\u0438\\u043a\\u0430 \\u043f\\u0440\\u0438\\u043d\\u044f\\u0442\\u0438\\u044f/\\u043e\\u0442\\u043a\\u043b\\u043e\\u043d\\u0435\\u043d\\u0438\\u044f \\u0440\\u0430\\u0437\\u0432\\u0451\\u0440\\u043d\\u0443\\u0442\\u0430 \\u0432 \\u00a710. \\u0414\\u043e\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u0440\\u0430\\u0437\\u043b\\u0438\\u0447\\u0430\\u044e\\u0442\\u0441\\u044f \\u0443\\u0437\\u043a\\u0438\\u0435 \\u043f\\u043e\\u0434-\\u0442\\u0435\\u0437\\u0438\\u0441\\u044b (\\u0441\\u043f\\u0435\\u0446\\u0438\\u0444\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c Hyena vs \\u0434\\u0432\\u0443\\u043d\\u0430\\u043f\\u0440\\u0430\\u0432\\u043b\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u0